mapper.select:
select distinct c.employee_code
from safety_depart_change_list c
       inner join safety_build_power p on c.EMPLOYEE_CODE = p.EMPLOYEE_CODE and p.IS_DELETE = 0
where c.change_type = #{changeType}
  and c.CREATE_TIME = #{createTime}

select sdcl.ID, sdcl.EMPLOYEE_CODE, sdcl.EMPLOYEE_NAME, sdcl.OLD_DEPT_CODE, sdcl.OLD_DEPT_NAME,sdcl.NEW_DEPT_NAME,
       sdcl.CREATE_TIME, sdcl.UPDATE_TIME, sdcl.change_type,sgi.org_code_path as NEW_DEPT_CODE
  from SAFETY.safety_depart_change_list sdcl,safety.safety_group_info sgi,safety
 where sdcl.NEW_DEPT_CODE  = sgi.code

  and sdcl.change_type = #{changeType}


   and sdcl.UPDATE_TIME >=  #{updateTimeBegin}



    and sdcl.UPDATE_TIME < #{updateTimeEnd}



    and sdcl.EMPLOYEE_CODE not like concat(#{employeeNoStart},'%')

select sdcl.ID, sdcl.EMPLOYEE_CODE, sdcl.EMPLOYEE_NAME, sdcl.OLD_DEPT_CODE, sdcl.OLD_DEPT_NAME,sdcl.NEW_DEPT_NAME,
sdcl.CREATE_TIME, sdcl.UPDATE_TIME, sdcl.change_type,sgi.org_code_path as NEW_DEPT_CODE,sem.USER_TYPE,SEM.face_issue_flag
from SAFETY.safety_depart_change_list sdcl,safety.safety_group_info sgi,safety.safety_employee_message sem
where sdcl.NEW_DEPT_CODE  = sgi.code
  and sem.emp_no = sdcl.EMPLOYEE_CODE and sem.status='NORMAL'

  and sdcl.change_type = #{changeType}


  and sdcl.UPDATE_TIME >=  #{updateTimeBegin}



    and sdcl.UPDATE_TIME < #{updateTimeEnd}



  and sdcl.EMPLOYEE_CODE not like concat(#{employeeNoStart},'%')

select EMPLOYEE_CODE from safety_depart_change_list
                     where UPDATE_TIME >= #{beginTime}

                       and UPDATE_TIME <= #{endTime}
